// 6.92.0 (plan r3, A-W10): the canonical filler fixture, generated by the server's own functions and
// pinned by sha256 in both repos (COS Control carries a byte-identical copy in Tests/fixtures/).
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { FILLER_FIXTURE_CASES, fillerFixtureOutput, renderFillerFixture } from './dictation-fillers-fixture-cases.js'
import { stripDisfluencies, stripFillersIfEnglish } from './dictation-fillers.js'
import { looksEnglish } from './dictation-meaning-guard.js'

const FIXTURE = new URL('./__fixtures__/dictation-fillers.json', import.meta.url)
/** Change only by regenerating the fixture; COS Control pins the same value. */
const FIXTURE_SHA256 = '56b5f60c49bf5e4d2ae3774496fd19e837aeb82217c2359cf541c4c614ef52b4'

describe('6.92.0 canonical filler fixture', () => {
  it('the fixture on disk is exactly what the server functions generate, and its sha256 is pinned', () => {
    const text = readFileSync(FIXTURE, 'utf8')
    const sha = createHash('sha256').update(text).digest('hex')
    console.log(`dictation-fillers.json sha256 ${sha} (${FILLER_FIXTURE_CASES.length} rows)`)
    expect(text).toBe(renderFillerFixture())
    expect(sha).toBe(FIXTURE_SHA256)
  })

  it('every row is what a person would want (hand-written), not only what the function returned', () => {
    for (const c of FILLER_FIXTURE_CASES) expect(fillerFixtureOutput(c.scope, c.input), c.id).toBe(c.want)
    const rows = JSON.parse(readFileSync(FIXTURE, 'utf8')).rows as Array<{ id: string; expected: string }>
    for (const row of rows) expect(row.expected, row.id).toBe(FILLER_FIXTURE_CASES.find(c => c.id === row.id)!.want)
  })

  it('scopes and counts are pinned: 103 "both" rows for the port, 23 language rows for the server gate', () => {
    const count = (scope: string) => FILLER_FIXTURE_CASES.filter(c => c.scope === scope).length
    expect([count('both'), count('server'), count('client')]).toEqual([103, 23, 0])
    expect(FILLER_FIXTURE_CASES.filter(c => c.group === 'exemption').length).toBe(25)
    expect(new Set(FILLER_FIXTURE_CASES.map(c => c.id)).size).toBe(FILLER_FIXTURE_CASES.length)
    // F1b: the exemption and non-English rows, 40 in all (25 exemptions, 15 not English).
    const notEnglish = FILLER_FIXTURE_CASES.filter(c => c.group === 'language' && c.input === c.want && c.input !== 'um 5 pm works')
    expect(notEnglish.length).toBe(15)
  })
})

// F1b: each token exemption on its own, so a mutant removing one character from a rule fails here.
describe('6.92.0 filler pass: token exemptions (F1b)', () => {
  it.each([
    ['before /', 'cd ~/uh'], ['before .', 'rename it to .um'], ['before @', 'ping @uh'], ['before _', 'set my_um'],
    ['before :', 'host:um'], ['before #', 'tag #um'], ['before $', 'echo $um'],
  ])('a filler right after a path or handle character is kept (%s)', (_label, input) => {
    expect(stripDisfluencies(input)).toBe(input)
  })

  it.each([
    ['after /', 'um/bin here'], ['after @', 'um@example.com'], ['after _', 'um_id please'], ['after #', 'um#12 now'], ['after $', 'um$ sign'],
    ['after . and a letter', 'um.py again'], ['after : and a digit', 'um:8080 first'],
  ])('a filler right before a path or code character is kept (%s)', (_label, input) => {
    expect(stripDisfluencies(input)).toBe(input)
  })

  it('a sentence-final period, ellipsis or colon is not a token character', () => {
    expect(stripDisfluencies('Let us ship it um.')).toBe('Let us ship it.')
    expect(stripDisfluencies('It was um... great')).toBe('It was great')
    expect(stripDisfluencies('The reason is um: we ran out')).toBe('The reason is: we ran out')
  })
})

// F1b: the language gate. "um" and "er" are words in German, Portuguese, Danish, Norwegian and Dutch.
describe('6.92.0 filler pass: language gate (F1b)', () => {
  it('a short text with foreign function words is not English, unless English ones outnumber them', () => {
    expect(looksEnglish('Wir treffen uns um 5 Uhr')).toBe(false)
    expect(stripFillersIfEnglish('Wir treffen uns um 5 Uhr')).toBe('Wir treffen uns um 5 Uhr')
    expect(looksEnglish('Send the deck to Dana, um, por favor')).toBe(true)
    // An all-caps token is an acronym, never foreign evidence.
    expect(looksEnglish('Send the MIT deck')).toBe(true)
  })

  it('an inline um or er needs an English function word beside it', () => {
    expect(stripFillersIfEnglish('Comprei um carro novo')).toBe('Comprei um carro novo')
    expect(stripFillersIfEnglish('Han er hjemme nu')).toBe('Han er hjemme nu')
    expect(stripFillersIfEnglish('ship it er tomorrow')).toBe('ship it tomorrow')
    // A paused filler ("Um, sure thing") is a hesitation in any case.
    expect(stripFillersIfEnglish('Um, sure thing')).toBe('Sure thing')
  })

  it('the server filler step is gated; the token rules alone are not', () => {
    expect(stripDisfluencies('Er kommt morgen.')).toBe('Kommt morgen.')
    expect(stripFillersIfEnglish('Er kommt morgen.')).toBe('Er kommt morgen.')
  })

  it('a short command with no foreign word and no inline um or er is still English (its names are checked)', () => {
    expect(looksEnglish('ping Marco re pricing')).toBe(true)
  })
})
